use crate::gui::utils::{read_state, state_color, state_icon, time_ago};

pub fn page(disks: &[(String, Option<String>, Option<Vec<String>>, bool)], targets: &[String], keep_last: u32, available: &[String], message: &str) -> String {
    let (state, detail, time) = read_state();
    let s_color = state_color(&state);
    let _s_icon = state_icon(&state);
    let t_str = time_ago(time);
    let all_selected_global = if targets.iter().any(|t| t == "all") { "sel" } else { "" };

    let mut available_chips_global = String::new();
    for a in available.iter() {
        let selected = if targets.iter().any(|t| t == a) { "sel" } else { "" };
        available_chips_global.push_str(&format!("<span class=\"chip {}\" onclick=\"toggleTarget(this,'{}')\">{}</span>", selected, a, a.to_uppercase()));
    }

    let mut disk_rows = String::new();
    for (i, (uuid, label, disk_targets, paused)) in disks.iter().enumerate() {
        let label_val = label.as_deref().unwrap_or("");
        let use_global = disk_targets.is_none();
        let checked = if use_global { "checked" } else { "" };
        let targets_hidden = if use_global { "style=\"display:none\"" } else { "style=\"display:block\"" };
        let disk_all_selected = if let Some(dt) = disk_targets { if dt.iter().any(|t| t == "all") { "sel" } else { "" } } else { "" };
        let mut disk_chips = String::new();
        disk_chips.push_str(&format!("<span class=\"chip {}\" onclick=\"toggleTargetDisk(this,{},'all')\">ALL</span>", disk_all_selected, i));
        for a in available.iter() {
            let selected = if let Some(dt) = disk_targets { if dt.iter().any(|t| t == a) { "sel" } else { "" } } else { "" };
            disk_chips.push_str(&format!("<span class=\"chip {}\" onclick=\"toggleTargetDisk(this,{},'{}')\">{}</span>", selected, i, a, a.to_uppercase()));
        }
        let paused_checked = if *paused { "checked" } else { "" };
        disk_rows.push_str(&format!("<div class=\"card\"><div class=\"card__head\"><span>DISK {}</span><button class=\"btn\" onclick=\"this.closest('.card').remove()\">X</button></div><div class=\"card__body\" style=\"padding:1rem 1.2rem\"><div><input name=\"disk_label_{}\" value=\"{}\" class=\"input\" placeholder=\"LABEL\" style=\"width:calc(100% - 8px);max-width:400px\"></div><div style=\"margin-top:.8rem\"><button class=\"btn btn--pri\" onclick=\"toggleDiskMore(this,{});return false;\" style=\"padding:.4rem .8rem;font-size:.75rem\">More</button></div><div id=\"diskmore_{}\" style=\"display:none;margin-top:.8rem\"><div style=\"margin-bottom:.6rem\"><input name=\"disk\" value=\"{}\" class=\"input\" placeholder=\"UUID\" style=\"min-width:400px;width:calc(100% - 8px);max-width:500px\"></div><div style=\"margin-top:.6rem\"><label style=\"font-size:.75rem\"><input type=\"checkbox\" name=\"disk_paused_{}\" {}> Pause</label></div><div style=\"margin-top:.6rem\"><label style=\"font-size:.75rem\"><input type=\"checkbox\" name=\"disk_use_global_{}\" {} onchange=\"toggleDiskTargets(this,{})\"> Use global targets</label><div id=\"disk_targs_{}\" {} style=\"margin-top:.6rem\">{}</div></div></div></div></div>", i+1, i, label_val.replace('"', "&quot;"), i, i, uuid.replace('"', "&quot;"), i, paused_checked, i, checked, i, i, targets_hidden, disk_chips));
    }

    let msg_html = if message.is_empty() { String::new() } else { format!("<div class=\"toast\">{}</div>", message) };

    let mut html = String::new();
    html.push_str("<!DOCTYPE html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>VZDUMPER</title><link href=\"https://fonts.googleapis.com/css2?family=JetBrains+Mono&family=Space+Grotesk:wght@700&display=swap\" rel=\"stylesheet\"><style>");
    html.push_str("*{margin:0;padding:0;box-sizing:border-box}:root{--ink:#000;--safety:#FF3E00;--h:44px}body{font-family:'JetBrains Mono',monospace;padding-top:var(--h)}.header{position:fixed;top:0;left:0;width:100%;height:var(--h);background:#000;color:#fff;display:flex;align-items:center;padding:0 2rem;border-bottom:2px solid var(--safety)}.header__inner{width:100%;max-width:1200px;margin:0 auto;display:flex;justify-content:space-between;align-items:center}.header__logo{font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:1rem;color:var(--safety)}.header__nav{display:flex}.header__nav a{padding:0 1rem;color:#aaa;cursor:pointer;font-size:1rem;font-family:'Space Grotesk',sans-serif;font-weight:700}.header__nav a.active{color:#fff;background:var(--safety)}.main{min-height:calc(100vh - 80px)}.container{max-width:1200px;margin:0 auto;padding:2rem}.tab{display:none}.tab.active{display:block}.card{border:4px solid #000;box-shadow:8px 8px 0 #000;margin-bottom:1rem;max-width:700px}.card__head{background:#000;color:#fff;padding:.6rem 1rem;display:flex;justify-content:space-between}.card__body{padding:1rem 1.2rem}.btn{border:3px solid #000;box-shadow:6px 6px 0 #000;padding:.6rem 1.2rem;background:#fff;cursor:pointer;font-family:'JetBrains Mono',monospace}.btn--pri{background:var(--safety);color:#fff}.input{font-family:'JetBrains Mono',monospace;border:2px solid #000;box-shadow:3px 3px 0 #000;padding:.4rem .5rem;background:#fff;margin:2px;font-size:.8rem}.chip{border:2px solid #000;box-shadow:3px 3px 0 #000;padding:.3rem .7rem;display:inline-block;margin:.3rem;cursor:pointer;font-size:.7rem}.chip.sel{background:var(--safety);color:#fff}.toast{position:fixed;bottom:1rem;left:50%;transform:translateX(-50%);background:#000;color:#fff;padding:.5rem 1rem;border:2px solid var(--safety);animation:fadeout 3s forwards}.footer{background:#000;color:#fff;padding:1rem 2rem}@keyframes fadeout{0%{opacity:1}80%{opacity:1}100%{opacity:0;visibility:hidden}}");
    html.push_str("</style></head><body><header class=\"header\"><div class=\"header__inner\"><div class=\"header__logo\">VZDUMPER</div><nav class=\"header__nav\"><a class=\"tab-link active\" data-t=\"d\">DASHBOARD</a><a class=\"tab-link\" data-t=\"disks\">DISKS</a><a class=\"tab-link\" data-t=\"cfg\">CONFIG</a><a class=\"tab-link\" data-t=\"sys\">SYSTEM</a></nav><div>CURRENT STATUS: <span style=\"color:");
    html.push_str(s_color); html.push_str("\">"); html.push_str(&state.to_uppercase()); html.push_str("</span></div></div></header>");
    html.push_str("<main class=\"main\"><section class=\"tab active\" id=\"t-d\"><div class=\"container\"><h1 style=\"font-family:'Space Grotesk',sans-serif;text-transform:uppercase;margin-bottom:1rem\">Dashboard</h1><div class=\"card\"><div class=\"card__head\"><span>STATUS</span><span style=\"color:");
    html.push_str(s_color); html.push_str("\">"); html.push_str(&state.to_uppercase()); html.push_str("</span></div><div class=\"card__body\"><div>"); html.push_str(&detail); html.push_str("</div><div style=\"color:var(--muted);margin-top:.5rem\">"); html.push_str(&t_str); html.push_str("</div></div></div></div></section>");
    html.push_str("<section class=\"tab\" id=\"t-disks\"><div class=\"container\"><h1 style=\"font-family:'Space Grotesk',sans-serif;text-transform:uppercase;margin-bottom:1rem\">Disks</h1><div class=\"card\"><div class=\"card__head\"><span>DISK MANAGER</span></div><div class=\"card__body\"><button class=\"btn btn--pri\" onclick=\"scan()\">SCAN</button><div id=\"dlist\" style=\"margin-top:1rem\"></div></div></div></div></section>");
    html.push_str("<section class=\"tab\" id=\"t-cfg\"><div class=\"container\"><h1 style=\"font-family:'Space Grotesk',sans-serif;text-transform:uppercase;margin-bottom:1rem\">Config</h1><form method=\"post\" action=\"/\" id=\"f\"><div class=\"card\"><div class=\"card__head\"><span>BACKUP DISKS</span></div><div class=\"card__body\"><div id=\"disks\">"); html.push_str(&disk_rows); html.push_str("</div><button type=\"button\" class=\"btn\" onclick=\"addDisk()\">+ ADD</button></div></div><div class=\"card\"><div class=\"card__head\"><span>GLOBAL TARGETS</span></div><div class=\"card__body\"><div id=\"chips\"><span class=\"chip "); html.push_str(all_selected_global); html.push_str("\" onclick=\"toggleTarget(this,'all')\">ALL</span>"); html.push_str(&available_chips_global); html.push_str("</div></div></div><div class=\"card\"><div class=\"card__head\"><span>RETENTION</span></div><div class=\"card__body\"><input type=\"number\" name=\"keep_last\" value=\""); html.push_str(&keep_last.to_string()); html.push_str("\" class=\"input\" style=\"width:60px\"></div></div><button class=\"btn btn--pri\">SAVE</button></form></div></section>");
    html.push_str("<section class=\"tab\" id=\"t-sys\"><div class=\"container\"><h1 style=\"font-family:'Space Grotesk',sans-serif;text-transform:uppercase;margin-bottom:1rem\">System</h1><div class=\"card\"><div class=\"card__head\"><span>TLS</span></div><div class=\"card__body\" id=\"tls\">--</div></div><div class=\"card\"><div class=\"card__head\"><span>VER</span></div><div class=\"card__body\">2.5.1</div></div></div></section></main>");
    html.push_str(&msg_html);
    html.push_str("<footer class=\"footer\">We're dumping</footer><script>");
    html.push_str("document.querySelectorAll('.tab-link').forEach(l=>{l.onclick=e=>{e.preventDefault();document.querySelectorAll('.tab-link').forEach(x=>x.classList.remove('active'));l.classList.add('active');document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.getElementById('t-'+l.dataset.t).classList.add('active');};});");
    html.push_str("function addDisk(){const i=document.querySelectorAll('#disks .card').length;const c=document.createElement('div');c.className='card';c.innerHTML='<div class=\"card__head\"><span>DISK '+(i+1)+'</span><button class=\"btn\" onclick=\"this.closest(\\'.card\\').remove()\">X</button></div><div class=\"card__body\" style=\"padding:1rem 1.2rem\"><div><input name=\"disk_label_'+i+'\" class=\"input\" placeholder=\"LABEL\" style=\"width:calc(100% - 8px);max-width:400px\"></div><div style=\"margin-top:.8rem\"><button class=\"btn btn--pri\" style=\"padding:.4rem .8rem;font-size:.75rem\" onclick=\"toggleDiskMore(this,'+i+');return false;\">More</button></div><div id=\"diskmore_'+i+'\" style=\"display:none;margin-top:.8rem\"><div style=\"margin-bottom:.6rem\"><input name=\"disk\" class=\"input\" placeholder=\"UUID\" style=\"min-width:400px;width:calc(100% - 8px);max-width:500px\"></div><div style=\"margin-top:.6rem\"><label style=\"font-size:.75rem\"><input type=\"checkbox\" name=\"disk_paused_'+i+'\"> Pause</label></div><div style=\"margin-top:.6rem\"><label style=\"font-size:.75rem\"><input type=\"checkbox\" name=\"disk_use_global_'+i+'\" checked onchange=\"toggleDiskTargets(this,'+i+')\"> Use global targets</label><div id=\"disk_targs_'+i+'\" style=\"margin-top:.6rem\"></div></div></div></div>';document.getElementById('disks').appendChild(c);}");
    html.push_str("function toggleDiskMore(a,i){const d=document.getElementById('diskmore_'+i);if(d.style.display==='none'||d.style.display===''){d.style.display='block';a.textContent='Less';}else{d.style.display='none';a.textContent='More';}}");
    html.push_str("function toggleDiskTargets(cb,i){const d=document.getElementById('disk_targs_'+i);d.style.display=cb.checked?'none':'block';}");
    html.push_str("function toggleTargetDisk(e,di,id){const cb=document.querySelector('input[name=\"disk_use_global_'+di+'\"]');if(cb&&cb.checked)cb.checked=false;const d=document.getElementById('disk_targs_'+di);if(d)d.style.display='block';e.classList.toggle('sel');const chips=e.parentElement.querySelectorAll('.chip');if(id==='all'&&e.classList.contains('sel')){chips.forEach(c=>{if(c!==e)c.classList.remove('sel');});}else if(id!=='all'){const a=e.parentElement.querySelector('.chip');if(a)a.classList.remove('sel');}}");
    html.push_str("function toggleTarget(e,id){e.classList.toggle('sel');const cs=document.querySelectorAll('#chips .chip');if(id==='all'&&e.classList.contains('sel')){cs.forEach(x=>{if(x!==e)x.classList.remove('sel');});}else if(id!=='all'){const a=document.querySelector('#chips .chip');if(a)a.classList.remove('sel');}}");
    html.push_str("document.getElementById('f').onsubmit=function(){this.querySelectorAll('input[name=target]').forEach(x=>x.remove());this.querySelectorAll('input[data-dt]').forEach(x=>x.remove());this.querySelectorAll('input[data-ug]').forEach(x=>x.remove());const sel=document.querySelectorAll('#chips .chip.sel');if(sel.length===0){const i=document.createElement('input');i.type='hidden';i.name='target';i.value='all';this.appendChild(i);}else{sel.forEach(x=>{const i=document.createElement('input');i.type='hidden';i.name='target';i.value=x.textContent.toLowerCase();this.appendChild(i);});}document.querySelectorAll('#disks .card').forEach((card,idx)=>{const ug=card.querySelector('input[name=\"disk_use_global_'+idx+'\"]');const hi=document.createElement('input');hi.type='hidden';hi.name='disk_use_global_'+idx;hi.value=ug&&ug.checked?'1':'0';hi.setAttribute('data-ug','1');this.appendChild(hi);if(ug&&!ug.checked){const d=card.querySelector('#disk_targs_'+idx);if(!d)return;const s=d.querySelectorAll('.chip.sel');if(s.length===0){const i=document.createElement('input');i.type='hidden';i.name='disk_target_'+idx;i.value='all';i.setAttribute('data-dt','1');this.appendChild(i);}else{s.forEach(x=>{const i=document.createElement('input');i.type='hidden';i.name='disk_target_'+idx;i.value=x.textContent.toLowerCase();i.setAttribute('data-dt','1');this.appendChild(i);});}}});};");
    html.push_str("setInterval(async()=>{try{const r=await fetch('/tls');const d=await r.json();const el=document.getElementById('tls');if(el)el.textContent=d.tls_enabled?'HTTPS':'HTTP';}catch(e){}},10000);");
    html.push_str("async function scan(){const l=document.getElementById('dlist');l.innerHTML='...';try{const r=await fetch('/disks');const ds=await r.json();if(!ds.length){l.innerHTML='NONE';return;}let h='';ds.forEach(d=>{h+='<div class=\"card\"><div class=\"card__head\"><span>'+d.device+'</span></div><div class=\"card__body\">'+(d.uuid&&d.fstype?'<button class=\"btn\" onclick=\"ud(\\''+d.device+'\\')\">USE</button>':'<button class=\"btn btn--pri\" onclick=\"fd(\\''+d.device+'\\')\">FORMAT</button>')+'</div></div>';});l.innerHTML=h;}catch(e){l.innerHTML='ERR';}}");
    html.push_str("async function ud(dev){const label=prompt('L')||'';const r=await fetch('/disks/use',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device:dev,label:label})});const res=await r.json();if(res.success)location.reload();else alert(res.error);}");
    html.push_str("async function fd(dev){if(prompt('TYPE '+dev)!==dev)return;const r=await fetch('/disks/format',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({device:dev,label:'',confirm:dev})});const res=await r.json();if(res.success)location.reload();else alert(res.error);}");
    html.push_str("setTimeout(()=>{document.querySelectorAll('.toast').forEach(t=>t.remove());},3200);");
    html.push_str("</script></body></html>");
    html
}
